<script>const rows=document.getElementById('rows');document.getElementById('addRow').onclick=()=>rows.append(rows.firstElementChild.cloneNode(true));rows.addEventListener('click',e=>{if(e.target.classList.contains('remove-row')&&rows.children.length>1)e.target.closest('.item-row').remove()});rows.addEventListener('change',e=>{if(e.target.name==='product_id[]'){e.target.closest('.item-row').querySelector('[name="unit_cost[]"]').value=e.target.selectedOptions[0].dataset.cost||''}});</script>
